import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.K3sFe4KB.js";const m=JSON.parse('{"title":"Keep state safe","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/keep-state-safe.md","filePath":"how-to/keep-state-safe.md"}'),i={name:"how-to/keep-state-safe.md"};function c(d,e,r,n,l,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="keep-state-safe" tabindex="-1">Keep state safe <a class="header-anchor" href="#keep-state-safe" aria-label="Permalink to &quot;Keep state safe&quot;">​</a></h1><p>This guide shows you how to manage <code>.cicada/state.yaml</code> — what to commit, how locking works, and how to recover a lost file.</p><h2 id="what-the-state-file-is" tabindex="-1">What the state file is <a class="header-anchor" href="#what-the-state-file-is" aria-label="Permalink to &quot;What the state file is&quot;">​</a></h2><p>Recorded state maps your stable local ids to the remote ids the provider assigned, plus the apply journal. It is the <strong>managed boundary</strong>: cicada only deletes or overwrites what this file records. Without it, plans are all-<code>create</code> and drift detection has nothing to compare.</p><p>Default location: <code>.cicada/state.yaml</code> beside the manifest. Override with <code>--state &lt;path&gt;</code> or <code>CICADA_STATE</code>.</p><h2 id="commit-it" tabindex="-1">Commit it <a class="header-anchor" href="#commit-it" aria-label="Permalink to &quot;Commit it&quot;">​</a></h2><p>Commit <code>state.yaml</code> alongside your calendar YAML. cicada&#39;s scaffolded <code>.cicada/.gitignore</code> already excludes the runtime artifacts:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fake-provider.json</span></span>
<span class="line"><span>*.lock</span></span></code></pre></div><ul><li><code>state.yaml</code> — <strong>commit.</strong> It is the shared record of what has been applied; losing it means re-adopting remote events.</li><li><code>fake-provider.json</code> — never commit; it&#39;s the demo backend.</li><li><code>*.lock</code> — lock files; never commit.</li><li>Secrets (<code>~/.local/state/cicada/secrets/</code>) — <strong>never</strong> inside the repo; OAuth refresh tokens and service-account keys live there at mode <code>0600</code>.</li></ul><p>State files are a real dependency — treat them like Terraform state. Multi-user teams should have one canonical copy.</p><h2 id="locking" tabindex="-1">Locking <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;Locking&quot;">​</a></h2><p><code>apply</code>, <code>refresh</code>, and the MCP <code>state.refresh</code>/<code>plan.apply</code> tools take an exclusive advisory <code>flock</code> on <code>state.yaml.lock</code> for their whole run. A concurrent <code>cicada</code> process or a long-running MCP server cannot interleave writes — a second process simply waits.</p><p>Writes are atomic (temp file + rename), so a crash leaves either the old or the new document, never a torn one.</p><h2 id="recover-a-lost-state-file" tabindex="-1">Recover a lost state file <a class="header-anchor" href="#recover-a-lost-state-file" aria-label="Permalink to &quot;Recover a lost state file&quot;">​</a></h2><p>Every event cicada writes carries provider-side tags (<code>cicada:id</code>, <code>cicada:managed</code>, <code>cicada:state</code> hash). If <code>state.yaml</code> is deleted:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # warns: live events already carry cicada:id tags</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # adopts tagged events back into recorded state —</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # no duplicates</span></span></code></pre></div><p>The plan lists each <code>create</code> with a warning that resume reconciliation will adopt the already-tagged remote event. Apply journals them <code>skippedAlreadyApplied</code> and rebuilds the recorded map.</p><p><code>cicada refresh</code> also reports <strong>adoption candidates</strong> — live events carrying cicada tags that recorded state doesn&#39;t know (e.g. applied by another machine sharing the calendar). They are reported, never auto-adopted.</p>`,18)])])}const k=a(i,[["render",c]]);export{m as __pageData,k as default};
